// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RelationshipObservation) predicate.RelationshipObservation {
	return predicate.RelationshipObservation(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RelationshipObservation) predicate.RelationshipObservation {
	return predicate.RelationshipObservation(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RelationshipObservation) predicate.RelationshipObservation {
	return predicate.RelationshipObservation(sql.NotPredicates(p))
}
